//! Binary triangle fixtures generated by external CAD tessellators for the assembly benchmark.

use iletki::{Bounds3, Mesh3D, PickId, Vec3, Vertex3D};
use std::{
    fs::File,
    io::{self, Read},
    path::Path,
};

const MAGIC: &[u8; 8] = b"ILTKM01\0";
const MAX_BYTES: u64 = 512 * 1024 * 1024;

pub(super) struct Fixture {
    pub(super) meshes: Vec<Mesh3D>,
    pub(super) bounds: Bounds3,
    pub(super) triangles: usize,
}

pub(super) fn load(path: &Path) -> io::Result<Fixture> {
    fn invalid(msg: &'static str) -> io::Error {
        io::Error::new(io::ErrorKind::InvalidData, msg)
    }
    fn read<const N: usize>(data: &mut &[u8]) -> io::Result<[u8; N]> {
        let mut bytes = [0; N];
        data.read_exact(&mut bytes)?;
        Ok(bytes)
    }
    fn xyz(data: &mut &[u8]) -> io::Result<[f32; 3]> {
        Ok([
            f32::from_le_bytes(read(data)?),
            f32::from_le_bytes(read(data)?),
            f32::from_le_bytes(read(data)?),
        ])
    }

    let file = File::open(path)?;
    let mut bytes = Vec::new();
    file.take(MAX_BYTES + 1).read_to_end(&mut bytes)?;
    if bytes.len() as u64 > MAX_BYTES {
        return Err(invalid("mesh fixture exceeds the byte limit"));
    }
    let mut data = bytes.as_slice();
    if read::<8>(&mut data)? != *MAGIC {
        return Err(invalid("invalid mesh fixture header"));
    }
    let count = u32::from_le_bytes(read(&mut data)?);
    let mut fixture = Fixture {
        meshes: Vec::new(),
        bounds: Bounds3::EMPTY,
        triangles: 0,
    };
    for _ in 0..count {
        let object = u32::from_le_bytes(read(&mut data)?);
        let origin = Vec3::new(
            f64::from_le_bytes(read(&mut data)?),
            f64::from_le_bytes(read(&mut data)?),
            f64::from_le_bytes(read(&mut data)?),
        );
        let vertices = u32::from_le_bytes(read(&mut data)?) as usize;
        if !origin.is_finite()
            || vertices == 0
            || !vertices.is_multiple_of(3)
            || vertices > data.len() / 28
        {
            return Err(invalid("invalid mesh fixture chunk"));
        }
        let mut mesh = Mesh3D::at_origin(origin);
        mesh.vertices.reserve(vertices);
        for _ in 0..vertices {
            let position = xyz(&mut data)?;
            let normal = xyz(&mut data)?;
            let color = read(&mut data)?;
            let [x, y, z] = position.map(f64::from);
            let local = Vec3::new(x, y, z);
            if !local.is_finite() || !normal.into_iter().all(f32::is_finite) {
                return Err(invalid("non-finite mesh fixture vertex"));
            }
            mesh.local_bounds.include(local);
            mesh.vertices.push(Vertex3D::new(position, normal, color));
        }
        mesh.pick_ids
            .resize(vertices, PickId::new(1, object, 0).to_rg32u());
        let bounds = mesh.world_bounds();
        if bounds.is_empty() {
            return Err(invalid("mesh fixture bounds overflow"));
        }
        fixture.bounds.include(bounds.min);
        fixture.bounds.include(bounds.max);
        fixture.triangles = fixture.triangles.saturating_add(vertices / 3);
        fixture.meshes.push(mesh);
    }
    if fixture.meshes.is_empty() || !data.is_empty() {
        return Err(invalid("invalid mesh fixture length"));
    }
    Ok(fixture)
}

pub(super) fn load_lod(path: &Path, full: &Fixture) -> io::Result<Vec<Mesh3D>> {
    let coarse = load(path)?;
    if coarse.meshes.len() != full.meshes.len()
        || !coarse
            .meshes
            .iter()
            .zip(&full.meshes)
            .all(|(coarse, full)| {
                coarse.origin == full.origin && coarse.pick_ids.first() == full.pick_ids.first()
            })
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "LOD fixture IDs and origins must match the full fixture",
        ));
    }
    Ok(coarse.meshes)
}
